grafo = {
    "ana": ["beto", "carla"],
    "beto": ["ana", "dario"],
    "carla": ["ana", "elena"],
    "dario": ["beto"],
    "elena": ["carla"],
}

def amigos_de_amigos(grafo, persona):
    directos = set(grafo[persona])
    segundo_grado = set()
    for amigo in directos:
        segundo_grado.update(grafo[amigo])
    segundo_grado -= directos
    segundo_grado.discard(persona)
    return sorted(segundo_grado)

print("amigos de amigos de ana:", amigos_de_amigos(grafo, "ana"))

filas_column_family = [
    {"region": "norte", "ventas": 100},
    {"region": "sur", "ventas": 150},
    {"region": "norte", "ventas": 80},
]

def sumar_columna(filas, columna_filtro, valor, columna_suma):
    return sum(f[columna_suma] for f in filas if f[columna_filtro] == valor)

print("ventas totales region norte:", sumar_columna(filas_column_family, "region", "norte", "ventas"))
